type Counter struct {
	mu    sync.Mutex // unexported: one per guardian
	total int
	hits  int        // invariant spans both fields
}

func (c *Counter) Add(delta int) {
	c.mu.Lock()
	defer c.mu.Unlock() // released on every path, panic included
	c.total += delta
	c.hits++
}

